/// <summary>
/// Data contract for METBatchMonitoringMultiTestController.
/// </summary>
[DataContract]
class METBatchMonitoringMultiTestContract extends METSysOperationTaskDataContract
{
    InventLocationId    inventLocationId;
    Integer             sleepMs;
    Integer             maxRecords;
    NoYes               generateError;
    guid                topProcessId;

}

Method.Source:
/// <summary>
/// Sets default values for dialog fields.
/// </summary>
public void initialize()
{
    super();
    threadCount   = 2;
    sleepMs       = 10;
}

[DataMember, SysOperationControlVisibilityAttribute(true)]
public InventLocationId parmInventLocationId(InventLocationId _inventLocationId = inventLocationId)
{
    inventLocationId = _inventLocationId;
    return inventLocationId;
}

[
    DataMember,
    SysOperationLabel(literalStr("@MET:METBatchMonitoringSleepMs")),
    SysOperationControlVisibilityAttribute(true)
]
public Integer parmSleepMs(Integer _sleepMs = sleepMs)
{
    sleepMs = _sleepMs;
    return sleepMs;
}

[
    DataMember,
    SysOperationLabelAttribute(literalStr("@MET:METBatchMonitoringMaxRecords")),
    SysOperationControlVisibilityAttribute(true)
]
public Integer parmMaxRecords(Integer _maxRecords = maxRecords)
{
    maxRecords = _maxRecords;
    return maxRecords;
}

[
    DataMember,
    SysOperationLabelAttribute(literalStr("@MET:METBatchMonitoringGenerateError")),
    SysOperationControlVisibilityAttribute(true)
]
public NoYes parmGenerateError(NoYes _generateError = generateError)
{
    generateError = _generateError;
    return generateError;
}

[DataMember, SysOperationControlVisibilityAttribute(false)]
public guid parmTopProcessId(guid _topProcessId = topProcessId)
{
    topProcessId = _topProcessId;
    return topProcessId;
}
